sample_sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Name of ICI" = 'Tremelimumab' AND "Monotherapy/combination" = 'Combination';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Renal cell' AND "Type of combination" = 'ICI+Anti-VEGF';

SELECT "Number of arms"
FROM clinical_trials
WHERE "Cancer type" = 'Mesothelioma';

SELECT "Trial name"
FROM clinical_trials
WHERE "Cancer type" = 'Breast' AND "Is any other biomarker used for inclusion" = 'Yes';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Type of combination" = 'ICI+BRAFi+MEKi';

SELECT "Name of ICI"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Class of ICI" = 'PD-L1' AND "Included in MA" = 'Yes';

SELECT "Name of ICI"
FROM clinical_trials
WHERE "Cancer type" = 'Small Cell Lung';

SELECT "Type of combination"
FROM clinical_trials
WHERE "Cancer type" = 'Esophageal/GEJ' AND "Monotherapy/combination" = 'Combination';

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Priamry Multiple, composite, or co-primary endpoints?" = 'Yes';

SELECT "Control regimen"
FROM clinical_trials
WHERE "Name of ICI" = 'Chemotherapy' AND "Cancer type" = 'Gastric/GEJ' AND "Control arm" = 'Chemo';

SELECT "Control arm"
FROM clinical_trials
WHERE "Cancer type" = 'Small Cell Lung' AND "Trial phase" = 'Phase 3';

SELECT "Control regimen"
FROM clinical_trials
WHERE "Cancer type" = 'NSCLC' AND "Control arm" = 'Chemo';

SELECT "Secondary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma';

SELECT "Year"
FROM clinical_trials
WHERE "Name of ICI" = 'Atezolizumab';

SELECT "Follow-up duration for primary endpoint(s) in months | Overall"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma';

SELECT "Type of follow-up given"
FROM clinical_trials
WHERE "Cancer type" = 'Breast';

SELECT "Secondary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Head and Neck';

SELECT "Type of therapy"
FROM clinical_trials
WHERE "Cancer type" = 'Prostate';

SELECT "Originial publication or Follow-up"
FROM clinical_trials
WHERE "Cancer type" = 'Esophageal/GEJ';

SELECT "Follow-up duration for primary endpoint(s) in months | Overall"
FROM clinical_trials
WHERE "Cancer type" = 'Hodgkin Lymphoma';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Type of combination" = 'ICI+BRAFi+MEKi';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Type of combination" = 'ICI+MEKi';

SELECT "Is PD-L1 positivity inclusion criteria"
FROM clinical_trials
WHERE "Cancer type" = 'Hepatocellular';

SELECT "Trial name"
FROM clinical_trials
WHERE "Name of ICI" = 'Pembrolizumab' AND "Cancer type" = 'Head and Neck' AND "Monotherapy/combination" = 'Monotherapy' AND "Is PD-L1 positivity inclusion criteria" = 'Yes';

SELECT "Trial name"
FROM clinical_trials
WHERE "Name of ICI" = 'Pembrolizumab' AND "Cancer type" = 'Head and Neck' AND "Monotherapy/combination" = 'Monotherapy' AND "Is PD-L1 positivity inclusion criteria" = 'Yes';

SELECT "Trial phase"
FROM clinical_trials
WHERE "Name of ICI" = 'Avelumab';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Class of ICI" = 'PD-1' AND "Monotherapy/combination" = 'Monotherapy' AND "Cancer type" = 'Bladder';

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Esophageal/GEJ' AND "Trial phase" = 'Phase 2';

SELECT "PubMed ID"
FROM clinical_trials
WHERE "Year" >= 2015;

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Class of ICI" = 'PD-1' AND "Monotherapy/combination" = 'Monotherapy' AND "Cancer type" = 'Bladder';

SELECT "Clinical setting"
FROM clinical_trials
WHERE "Cancer type" = 'Hodgkin Lymphoma';

SELECT "Total sample size"
FROM clinical_trials
WHERE "Name of ICI" = 'Avelumab';

SELECT "Control regimen"
FROM clinical_trials
WHERE "Name of ICI" = 'Chemotherapy' AND "Cancer type" = 'Gastric/GEJ' AND "Control arm" = 'Chemo';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'NSCLC' AND "Type of combination" = 'ICI+TKI';

SELECT "Trial name"
FROM clinical_trials
WHERE "Cancer type" = 'Urothelial' AND "Control arm" = 'Placebo';

SELECT "Trial name"
FROM clinical_trials
WHERE "Name of ICI" = 'Avelumab' AND "Cancer type" = 'Multiple Myeloma';
